class Solution:
    def judgeSquareSum(self, c: int) -> bool:
        low, high = 0, int(c**0.5)

        while low <= high:
            total = low**2 + high**2

            if total == c:
                return True
            elif total > c:
                high -= 1
            else:
                low += 1
        return False
